cypress_script:
cy.visit('https://www.saucedemo.com/');
cy.get('[data-test="username"]').type('standard_user');
cy.get('[data-test="password"]').type('secret_sauce');
cy.get('[data-test="login-button"]').click();
cy.visit('https://www.saucedemo.com/checkout-step-two.html');
describe('Checkout Overview', () => {
  it('should display the checkout overview and totals correctly', () => {
    cy.url().should('include', '/checkout-step-two.html');
    cy.get('[data-test="secondary-header"]').should('be.visible');
    cy.get('[data-test="cart-list"]').should('be.visible');
    cy.get('[data-test="payment-info-label"]').should('contain', 'Payment Information:');
    cy.get('[data-test="payment-info-value"]').should('contain', 'SauceCard #31337');
    cy.get('[data-test="shipping-info-label"]').should('contain', 'Shipping Information:');
    cy.get('[data-test="shipping-info-value"]').should('contain', 'Free Pony Express Delivery!');
    cy.get('[data-test="total-info-label"]').should('contain', 'Price Total');
    cy.get('[data-test="subtotal-label"]').should('contain', 'Item total: $0');
    cy.get('[data-test="tax-label"]').should('contain', 'Tax: $0.00');
    cy.get('[data-test="total-label"]').should('contain', 'Total: $0.00');
  });
  it('should allow the user to cancel the checkout and return to the previous screen', () => {
    cy.get('[data-test="cancel"]').click();
    cy.url().should('include', '/cart.html');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';
test.beforeEach(async ({ page }) => {
  await page.goto('https://www.saucedemo.com/');
  await page.fill('[data-test="username"]', 'standard_user');
  await page.fill('[data-test="password"]', 'secret_sauce');
  await page.click('[data-test="login-button"]');
});
test.describe('Checkout Overview', () => {
  test('should display the checkout overview and totals correctly', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/checkout-step-two.html');
    await expect(page).toHaveURL(/checkout-step-two.html/);
    await expect(page.locator('[data-test="secondary-header"]')).toBeVisible();
    await expect(page.locator('[data-test="cart-list"]')).toBeVisible();
    await expect(page.locator('[data-test="payment-info-label"]')).toHaveText('Payment Information:');
    await expect(page.locator('[data-test="payment-info-value"]')).toHaveText('SauceCard #31337');
    await expect(page.locator('[data-test="shipping-info-label"]')).toHaveText('Shipping Information:');
    await expect(page.locator('[data-test="shipping-info-value"]')).toHaveText('Free Pony Express Delivery!');
    await expect(page.locator('[data-test="total-info-label"]')).toHaveText('Price Total');
    await expect(page.locator('[data-test="subtotal-label"]')).toHaveText('Item total: $0');
    await expect(page.locator('[data-test="tax-label"]')).toHaveText('Tax: $0.00');
    await expect(page.locator('[data-test="total-label"]')).toHaveText('Total: $0.00');
  });
  test('should allow the user to cancel the checkout and return to the previous screen', async ({ page }) => {
    await page.click('[data-test="cancel"]');
    await expect(page).toHaveURL(/cart.html/);
  });
});
